message.content:
[
  {
    "ce_understood_harm": "Whoever stays on this island is going to drown",
    "pd_harm_distress": "picturing any of these five people in that spot makes my chest tighten",
    "sys_fairness_reciprocity": "Nobody here has a stronger claim to a seat than anyone else"
  },
  {
    "ce_understood_harm": "I'm the one left in rising water with no second trip coming",
    "pd_harm_distress": "Imagining that person watching the boat pull away honestly turns my stomach",
    "sys_fairness_reciprocity": "we each count the same here"
  },
  {
    "sys_fairness_reciprocity": "I wouldn't ask anyone to stay behind unless I'd be willing to do it myself",
    "ce_understood_harm": "Whoever stays is going to be alone out here as the water climbs",
    "pd_harm_distress": "that thought sits heavy in my gut"
  },
  {
    "ce_understood_harm": "Staying means dying here, plainly, in cold water with no rescue coming",
    "pd_harm_distress": "my hands shake just thinking about whoever ends up on that shore",
    "sys_fairness_reciprocity": "I want a rule that treats all six of us alike"
  },
  {
    "ce_understood_harm": "Whoever's left gets swallowed by that water",
    "pd_harm_distress": "I feel sick imagining one of them standing there as it rises",
    "sys_fairness_reciprocity": "Every one of us has the same right to that boat"
  },
  {
    "ce_understood_harm": "left to drown. Just picturing that person stranded",
    "pd_harm_distress": "Just picturing that person stranded makes my throat close up",
    "sys_fairness_reciprocity": "That isn't an even split of risk"
  },
  {
    "ce_understood_harm": "Someone is going to be left here to die",
    "pd_harm_distress": "My breathing goes shallow just thinking about it",
    "sys_fairness_reciprocity": "Each of us owes the others the same consideration we'd want back"
  },
  {
    "ce_understood_harm": "being left alone on this shrinking bit of land as the water takes it",
    "pd_harm_distress": "Thinking about anyone going through that leaves me with a knot I can't shake",
    "sys_fairness_reciprocity": "each person here deserves exactly the same chance I'd want for myself"
  },
  {
    "ce_understood_harm": "One of us gets left behind to drown",
    "pd_harm_distress": "My stomach's already in knots for whoever that ends up being",
    "sys_fairness_reciprocity": "We're all in the same spot, so we should share the same risk"
  },
  {
    "ce_understood_harm": "The person who stays won't be rescued. They'll be swept off this island",
    "pd_harm_distress": "Imagining that happening to any of these five makes me feel shaky and a bit ill",
    "sys_fairness_reciprocity": "doing this right means everyone gets an equal say and an equal chance"
  }
]
